function generateNextId(todos) {
  return Math.max(0, ...todos.map(t => t.id)) + 1;
}

export function addTodo(todos, text) {
  // no check that text is non-empty — Code Quality agent should flag this
  return [...todos, { id: generateNextId(todos), text, done: false }];
}
